import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import { useAuth } from '../../context/AuthContext';

const Dashboard = () => {
    const { user } = useAuth();
    const [stats, setStats] = useState({
        totalEmployees: 0,
        presentToday: 0,
        absentToday: 0,
        lateToday: 0
    });
    const [recentAttendance, setRecentAttendance] = useState([]);

    useEffect(() => {
        fetchStats();
        fetchRecentAttendance();
    }, []);

    const fetchStats = async () => {
        try {
            const today = new Date().toISOString().split('T')[0];
            const [employeesRes, attendanceRes] = await Promise.all([
                api.get('/employees'),
                api.get(`/attendance/report?startDate=${today}&endDate=${today}`)
            ]);

            const attendance = attendanceRes.data.data || [];
            setStats({
                totalEmployees: employeesRes.data.data?.length || 0,
                presentToday: attendance.filter(a => a.Status === 'Present').length,
                absentToday: attendance.filter(a => !a.CheckInTime).length,
                lateToday: attendance.filter(a => a.Status === 'Late').length
            });
        } catch (error) {
            console.error('Error fetching stats:', error);
        }
    };

    const fetchRecentAttendance = async () => {
        try {
            const endDate = new Date().toISOString().split('T')[0];
            const startDate = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
            const response = await api.get(`/attendance/report?startDate=${startDate}&endDate=${endDate}`);
            setRecentAttendance(response.data.data || []);
        } catch (error) {
            console.error('Error fetching recent attendance:', error);
        }
    };

    return (
        <div className="container mt-4">
            <h2>Dashboard</h2>
            <div className="row mt-4">
                <div className="col-md-3">
                    <div className="card text-white bg-primary mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Total Employees</h5>
                            <h2>{stats.totalEmployees}</h2>
                        </div>
                    </div>
                </div>
                <div className="col-md-3">
                    <div className="card text-white bg-success mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Present Today</h5>
                            <h2>{stats.presentToday}</h2>
                        </div>
                    </div>
                </div>
                <div className="col-md-3">
                    <div className="card text-white bg-danger mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Absent Today</h5>
                            <h2>{stats.absentToday}</h2>
                        </div>
                    </div>
                </div>
                <div className="col-md-3">
                    <div className="card text-white bg-warning mb-3">
                        <div className="card-body">
                            <h5 className="card-title">Late Today</h5>
                            <h2>{stats.lateToday}</h2>
                        </div>
                    </div>
                </div>
            </div>
            
            <div className="row mt-4">
                <div className="col-md-12">
                    <div className="card">
                        <div className="card-header bg-info text-white">
                            <h5>Recent Attendance (Last 7 Days)</h5>
                        </div>
                        <div className="card-body">
                            <div className="table-responsive">
                                <table className="table table-striped">
                                    <thead>
                                        <tr>
                                            <th>Employee</th>
                                            <th>Date</th>
                                            <th>Check In</th>
                                            <th>Check Out</th>
                                            <th>Status</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {recentAttendance.slice(0, 10).map((att, index) => (
                                            <tr key={index}>
                                                <td>{att.FirstName} {att.LastName}</td>
                                                <td>{new Date(att.AttendanceDate).toLocaleDateString()}</td>
                                                <td>{att.CheckInTime || '-'}</td>
                                                <td>{att.CheckOutTime || '-'}</td>
                                                <td>
                                                    <span className={`badge bg-${att.Status === 'Present' ? 'success' : att.Status === 'Late' ? 'warning' : 'danger'}`}>
                                                        {att.Status || 'Absent'}
                                                    </span>
                                                </td>
                                            </tr>
                                        ))}
                                        {recentAttendance.length === 0 && (
                                            <tr>
                                                <td colSpan="5" className="text-center">No attendance records found</td>
                                            </tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
